{
  "scenario_id": "sc-042304",
  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "CI",
      "years": [2021, 2022],
      "pattern": "shock",
      "direction": "increase",
      "magnitude": "Abrupt flat-topped two-year level shift of roughly +0.35 to +0.37: CI A/E moves from about 0.88 in 2020 to about 1.27-1.30 in 2021-2022, then reverts to about 0.94 in 2023-2024.",
      "confidence": 0.9,
      "evidence": [
        "artifacts/ae_ci_by_year.csv: 2020 AE=0.880, 2021 AE=1.273, 2022 AE=1.295, 2023 AE=0.937, 2024 AE=0.944.",
        "Computed evidence pack: CI step +0.196 at 2021 (score 1.9); best excursion 2021-2022 +0.362 (score 20.1); onset ratio 1.09 indicates the excursion arrives essentially in one year and holds, so this is a shock rather than a gradual drift.",
        "CI overdispersion is elevated (x6.33 vs Poisson), so the finding is based on the sustained level shift rather than on individual Poisson z-scores."
      ],
      "recommended_action": "Investigate CI claims, coding, severity mix, diagnosis mix, exposure, and expected-rate assumptions for 2021-2022 to determine whether the pulse is a data/classification event, genuine experience deterioration, or model misfit. If confirmed, review CI pricing/valuation assumptions and monitor 2023-2024 before applying any persistent trend adjustment."
    }
  ]
}

